// Boot and wiring (CONTRACTS.md): settings and kv, data, the shared ctx every view gets, routes (three tabs:
// 今天 / 查词 / 单词; lesson and dictation pushed from 今天, 家长区 pushed from 单词, the first open), the status line,
// badge, sheet, service worker.
// Owner: 接线. Other agents do not edit this file; they put what they need from it in their `needs`.
import { VERSION, DEFAULT_SETTINGS } from './config.js';
import { idbStore, loadSettings } from './db.js';
import { createAI } from './ai.js';
import { createWords, hasExtras } from './words.js';
import { createDict } from './dict.js';
import { createSpeech } from './speech.js';
import { createTTS, createPlayer, createVoice } from './tts.js';
import { bannerSpecs, shrinkState, pickStatus } from './banners.js';
import { TABS, SECTIONS, resolveRoute, reselectAction } from './nav.js';
import { h, icon, toast } from './ui-dom.js';
import { createEntryView } from './ui-entry.js';
import { createLookTab } from './ui-look.js';
import { createLibTab } from './ui-lib.js';
import { createEvents } from './events.js';
import { createBudget, wrapFetch } from './budget.js';
import { loadCurriculum, createCurriculum } from './curriculum.js';
import { createLines, FILE as LINES_FILE } from './lines.js';
import { planToday, wordsForPlan, dayOf } from './plan.js';
import { kidMessage, needsParent } from './kid-errors.js';
import { levelLabel, lookupHints } from './prompts.js';
import { createHomeTab } from './ui-home.js';
import { lessonDays } from './ui-home.js';
import { createLessonView } from './ui-lesson.js';
import { createDictationView } from './ui-dictation.js';
import { createParentView } from './ui-parent.js';
import { createOnboardView } from './ui-onboard.js';

const params = new URLSearchParams(location.search);
// ?mock=offline: mock mode where every model call fails like a dropped connection (tests the dictionary fallback)
const mockOffline = params.get('mock') === 'offline';
const mockForced = params.get('mock') === '1' || mockOffline;
const standalone = (window.matchMedia && matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true;

let settings = structuredClone(DEFAULT_SETTINGS);
let lastExport = null;      // {at, count, total}
let shrink = null;          // {now, then} when the library shrank by 20%+ since the last export
let updateReady = false;
let busyCount = 0;
let route = 'home';
const scrollPos = {};
const views = new Set();
const statusSlots = new Set();

// ---------------------------------------------------------------- kv: async store with a sync cache
// Everything in the kv store is read once at boot (it is small), so views can read it synchronously with peek().
const kvCache = new Map();
const kv = {
  peek: (key, fallback = undefined) => (kvCache.has(key) ? structuredClone(kvCache.get(key)) : fallback),
  async get(key, fallback = undefined) {
    if (kvCache.has(key)) return structuredClone(kvCache.get(key));
    const v = await idbStore.kvGet(key);
    if (v !== undefined) kvCache.set(key, v);
    return v === undefined ? fallback : structuredClone(v);
  },
  async set(key, value) { kvCache.set(key, structuredClone(value)); await idbStore.kvSet(key, value); },
  async delete(key) { kvCache.delete(key); await idbStore.kvDelete(key); },
  keys: (prefix = '') => [...kvCache.keys()].filter(k => k.startsWith(prefix)),
};

const liveSettings = () => ({ ...settings, mock: !!settings.mock || mockForced, mockFail: mockOffline ? 'network' : '' });
const budget = createBudget({ kv, getCap: () => settings.dailyCapYuan, getKindCaps: () => settings.kindCapsYuan || {} });
const ai = createAI({ getSettings: liveSettings, budget });
// Offline base dictionary: same-origin files, cached by the service worker.
// A network failure is an English TypeError on iOS ("Load failed"), so it gets a Chinese message here.
const DICT_NET_MSG = '网络不通，连上网后点“重试”';
const dict = createDict({
  fetchText: async name => {
    let res;
    try { res = await fetch('data/' + name); } catch (e) { console.warn('dictionary fetch:', (e && e.message) || e); throw new Error(DICT_NET_MSG); }
    if (!res.ok) throw new Error(`下载 ${name} 失败（${res.status}）`);
    try { return await res.text(); } catch (e) { console.warn('dictionary read:', (e && e.message) || e); throw new Error(DICT_NET_MSG); }
  },
});
const fetchJSON = async path => { const r = await fetch(path); if (!r.ok) throw new Error(`${path} ${r.status}`); return r.json(); };
// The program decides the level label and passes the textbook meaning and the words she has met (prompts.js);
// the curriculum is read when a lookup runs, so a reload after a textbook import is picked up.
const words = createWords({ store: idbStore, ai, dict,
  hintsFor: q => lookupHints(q, { curriculum, progress: kv.peek('progress', null) }),
  levelFor: w => levelLabel(w, curriculum) });
const speech = createSpeech({ getVoiceName: () => settings.voice });
// Qwen voice through one shared <audio> element (sounds on silent), clips cached in IndexedDB; the system voice is the
// fallback. Paid synthesis goes through the budget (budget.wrapFetch).
const tts = createTTS({ getSettings: liveSettings, store: idbStore, fetchImpl: wrapFetch(null, budget) });
const voice = createVoice({ speech, tts, player: createPlayer(), getSettings: liveSettings, notify: msg => toast(msg, 3500),
  onProblem: () => { if (parent) parent.onChange(); } });
const events = createEvents({ store: idbStore });
let curriculum = createCurriculum({});
let lines = createLines({});
// units come from kv 'textbook' and from the unit fields of imported words; word forms from the offline dictionary
const curriculumNow = () => loadCurriculum({ fetchJSON, kv, dict, entries: () => words.all() });
const DEFAULT_PARENT = '家长';
const parentName = () => String(((kv.peek('profile', {}) || {}).parentCall) || '').trim() || DEFAULT_PARENT;

let look, lib, home, lesson, dictation, parent, onboard;
let sheetView = null;

// The ctx every view gets (CONTRACTS.md "ctx"). Called `app` inside the dictionary's views.
const app = {
  version: VERSION,
  // data and services
  store: idbStore, kv, words, dict, ai, tts, voice, speech, events, budget,
  get curriculum() { return curriculum; },
  get lines() { return lines; },
  // after the textbook import writes kv 'textbook' (CONTRACTS.md "课本导入")
  async reloadCurriculum() { curriculum = await curriculumNow(); for (const v of [home, lib]) if (v && v.onChange) v.onChange(); return curriculum; },
  say: (text, button, opts) => voice.say(text, button, opts),
  // settings
  settings: () => settings,
  async saveSettings(patch) {
    settings = { ...settings, ...patch, models: { ...settings.models, ...(patch.models || {}) },
      poeModels: { ...settings.poeModels, ...(patch.poeModels || {}) } };
    // per-task routing (ai.js route) merges task by task, so changing one row keeps the others
    if (patch.routing || settings.routing) settings.routing = { ...(settings.routing || {}), ...(patch.routing || {}) };
    if ('newPerDay' in patch) updateBadge();
    await kv.set('settings', settings);
  },
  mockForced: () => mockForced,
  // today's lesson (plan.js): state assembled here from words, curriculum and kv
  // words carry r / last / order / source (wordsForPlan with { now }): surest first, today's reviews skipped, textbook order.
  // lessonDays: first lesson (none yet), comeback day (last one before yesterday), this week's count.
  // dictationTonight: a dictation record for today exists (dictation.js writes it after the first check, already done).
  planState(extra = {}) {
    const now = new Date();
    const day = dayOf(now);
    const dayRec = kv.peek('day:' + day, {}) || {};
    let unitRanks;
    try { unitRanks = Object.fromEntries((curriculum.units() || []).map(u => [u.id, u.order])); } catch (e) { unitRanks = undefined; }
    return {
      words: wordsForPlan(words.favorites(), curriculum, { now }),
      newPerDay: settings.newPerDay,
      newDoneToday: words.newDoneToday(),
      doneToday: dayRec.cells || {},
      light: false,
      dictationTonight: !!kv.peek('dictation:' + day, null),
      progress: kv.peek('progress', {}) || {},
      weekGoal: (kv.peek('profile', {}) || {}).weeklyGoal || 0,
      lessonDays: lessonDays(kv),
      unitRanks: unitRanks && Object.keys(unitRanks).length ? unitRanks : undefined,
      ...extra,
    };
  },
  todayPlan: (extra = {}) => planToday(app.planState(extra), new Date()),
  // errors Emma sees (kid-errors.js); "家长" becomes what the parent asked to be called (kv profile.parentCall)
  parentName: () => parentName(),
  kidError: (err, opts) => kidMessage(err, opts).replace(/家长/g, parentName()),
  needsParent: err => needsParent(err),
  // navigation
  go: (name, p = {}) => showRoute(name, { params: p }),
  back: () => { const r = resolveRoute(route); showRoute(r.parent || 'home'); },
  currentTab: () => resolveRoute(route).tab,
  currentRoute: () => route,
  toast: (msg, ms) => toast(msg, ms),
  // the dictionary's view API (ui-look, ui-lib, ui-entry use these)
  lookup(q, opts) { closeSheet(); showRoute('look'); look.lookup(q, opts); },
  backToZh() { look.backToZh(); },
  async toggleFav(slug, on) {
    try {
      await words.favorite(slug, on);
      toast(on ? '已加进单词本' : '已移出单词本，回到“最近查过”');
    } catch (e) { toast(e.message || String(e)); }
  },
  async regen(e) {
    try {
      const r = await words.lookup(e.headword, '', { force: true });
      if (!r.ok) toast(r.message, 3000);
      else if (r.found === false) toast('这次没认出这个词，讲解没变。', 3000);
      else toast('讲解已更新，其余部分正在生成');
    } catch (err) { toast(app.kidError(err, { where: 'look' }), 3500); }
  },
  registerView: v => views.add(v),
  unregisterView: v => views.delete(v),
  // old names: 'me' opens 家长区, 'review' opens 今天 (nav.js ALIASES)
  showTab: t => showRoute(t),
  openMe: (opts = {}) => showRoute('parent', { params: opts }),
  closeMe: () => showRoute('lib'),
  scrollTop: () => window.scrollTo(0, 0),
  openSheet: (slug, opts) => openSheet(slug, opts),
  updateBadge: () => updateBadge(),
  refreshBanners: () => { checkShrink(); renderStatus(); },
  // every tab root has one status slot under its running head; they all show the same line
  statusSlot: el => { statusSlots.add(el); renderStatusInto(el); },
  chrome: () => chrome(),
  lastExport: () => lastExport,
  async recordExport({ at = new Date().toISOString(), count, total }) {
    lastExport = { at, count, total };
    await idbStore.setMeta('lastExport', lastExport);
    checkShrink();
    renderStatus();
  },
  busy: d => { busyCount = Math.max(0, busyCount + d); },
  // theme color picked on the first open (index.html :root[data-accent])
  applyTheme: name => { if (name) document.documentElement.dataset.accent = name; else delete document.documentElement.dataset.accent; },
};

// ---------------------------------------------------------------- routes and the tab bar
const tabbar = document.getElementById('tabbar');
const tabButtons = {};
function buildTabbar() {
  tabbar.replaceChildren();
  const lit = resolveRoute(route).tab;
  for (const [k, label, ic] of TABS) {
    const b = h('button', { type: 'button', className: 'tb' + (k === lit ? ' on' : ''), 'aria-label': label, dataset: { tab: k },
      on: { click: () => (k === resolveRoute(route).tab ? reselect() : showRoute(k)) } },
    icon(ic), h('span', { className: 'tb-label', text: label }), k === 'home' ? h('span', { className: 'count', hidden: true }) : null);
    if (k === lit) b.setAttribute('aria-current', 'page');
    tabButtons[k] = b;
    tabbar.append(b);
  }
}
const viewOf = name => ({ home, lesson, dictation, look, lib, parent, onboard })[name];
function showRoute(name, { force = false, params: p = null } = {}) {
  const r = resolveRoute(name);
  if (r.name === route && !force && !p) return;
  voice.stop();
  scrollPos[route] = window.scrollY;
  if (route === 'lib' && lib && r.name !== 'lib') lib.hide();
  if (route === 'parent' && parent && r.name !== 'parent') parent.hide();   // the parent area locks again (ui-parent.js)
  const from = route;
  route = r.name;
  for (const s of SECTIONS) { const el = document.getElementById('tab-' + s); if (el) el.hidden = s !== r.section; }
  for (const [k] of TABS) {
    const b = tabButtons[k];
    if (b) { b.classList.toggle('on', k === r.tab); if (k === r.tab) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); }
  }
  const mod = viewOf(r.name);
  if (mod && mod.show) mod.show(p || {}, { from });
  chrome();
  window.scrollTo(0, p ? 0 : scrollPos[route] || 0);
}
function reselect() {
  const a = reselectAction(route);
  if (a.go) { showRoute(a.go); return; }
  if (route === 'lib' && lib.inDetail()) { lib.back(); return; }
  if (route === 'look' && look.isPushed()) { look.back(); return; }
  window.scrollTo({ top: 0, behavior: 'smooth' });
  if (route === 'look') look.focus();
}
// A pushed word page brings its own action bar, so the tab bar steps aside; so it does on immersive routes.
function chrome() {
  const pushed = (route === 'look' && look && look.isPushed()) || (route === 'lib' && lib && lib.isPushed());
  document.body.classList.toggle('pushed', !!pushed);
  document.body.classList.toggle('in-session', !!resolveRoute(route).immersive);
}

// ---------------------------------------------------------------- live updates
let changeTimer = 0;
words.onChange(({ type, slug }) => {
  // an import adds unit words: the curriculum's unit index is rebuilt from the entries
  if (type === 'import' && curriculum && curriculum.refresh) { try { curriculum.refresh(); } catch (e) { console.warn('curriculum refresh:', (e && e.message) || e); } }
  for (const v of views) {
    if (!slug || v.slug === slug) v.update(v.slug ? words.get(v.slug) : undefined);
  }
  clearTimeout(changeTimer);
  changeTimer = setTimeout(() => {
    for (const v of [look, lib, home, lesson, dictation, parent]) if (v && v.onChange) v.onChange();
    updateBadge();
  }, 50);
});

// ---------------------------------------------------------------- sheet (the full entry from a card)
const sheet = document.getElementById('sheet');
function openSheet(slug, { session = '', back = '返回' } = {}) {
  const e = words.get(slug);
  if (!e) return;
  closeSheet();
  sheetView = createEntryView(app, { where: 'sheet', back: { label: back, onClick: closeSheet }, session, scrollRoot: sheet });
  sheet.replaceChildren(sheetView.el);
  views.add(sheetView);
  sheetView.show(e, {});
  sheet.hidden = false;
  sheet.scrollTop = 0;
  document.body.classList.add('sheet-open');
  if (!hasExtras(e) || e.needs_core) words.enrich(slug).catch(() => {});
}
function closeSheet() {
  if (!sheetView) return;
  voice.stop();
  views.delete(sheetView);
  sheetView.destroy();
  sheetView = null;
  sheet.hidden = true;
  sheet.replaceChildren();
  document.body.classList.remove('sheet-open');
}

// ---------------------------------------------------------------- status line, badge
function checkShrink() {
  shrink = shrinkState(words.favorites().length, lastExport);
}
// One quiet line under the running head: the most important notice only (banners.js pickStatus).
let statusNow = null;
function renderStatus() {
  const online = typeof navigator.onLine === 'boolean' ? navigator.onLine : true;
  statusNow = pickStatus(bannerSpecs({ standalone, shrink, mockOffline, mock: !!settings.mock || mockForced, updateReady, online }));
  for (const el of statusSlots) renderStatusInto(el);
}
function renderStatusInto(el) {
  const s = statusNow;
  const actions = { restore: () => showRoute('parent', { params: { open: 'import' } }) };
  el.replaceChildren(...(s ? [h('p', { className: 'status-line' + (s.danger ? ' danger' : ''), role: s.danger ? 'alert' : 'status' },
    icon(s.icon), h('span', { text: s.text }),
    s.btn ? h('button', { type: 'button', className: 'text-btn accent', text: s.btn, on: { click: actions[s.action] } }) : null)] : []));
}

// The count on the 今天 tab: the warm-up cards today's plan still has (no app-icon badge: no notifications for a
// child's iPad). Same numbers as the home page, so a finished lesson shows no count.
function badgeCount() {
  try {
    const warm = app.todayPlan().cells.find(c => c.id === 'warmup');
    return warm && warm.status === 'ready' ? (warm.items || []).length : 0;
  } catch (e) { return words.dueCount(settings.newPerDay); }
}
function updateBadge() {
  const n = badgeCount();
  const b = tabButtons.home && tabButtons.home.querySelector('.count');
  if (b) { b.hidden = !n; b.textContent = n > 99 ? '99+' : String(n); }
  if (tabButtons.home) tabButtons.home.setAttribute('aria-label', n ? `今天，还有 ${n} 个词要复习` : '今天');
}

// ---------------------------------------------------------------- service worker
// Nothing that a reload would break: no lookup running, no lesson or dictation, sheet, unsent text, pending import.
function isIdle() {
  const a = document.activeElement;
  const typing = a && /INPUT|TEXTAREA/.test(a.tagName) && a.value;
  return !busyCount && !(look && look.isBusy()) && !(lesson && lesson.inSession()) && !(dictation && dictation.inSession()) &&
    !sheetView && !typing && !words.enriching() && !(parent && parent.holding());
}
// Stricter, for a reload while the app is in use: nothing being read either.
const isQuiet = () => isIdle() && !(look && look.hasResult()) && !(lib && lib.inDetail());

let swReg = null;
let reloaded = false;
function reloadOnce() { if (reloaded) return; reloaded = true; location.reload(); }
function registerSW() {
  if (!('serviceWorker' in navigator)) return;
  const local = /^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname);
  if (!((location.protocol === 'https:' && !local) || params.has('sw'))) return;
  const hadController = !!navigator.serviceWorker.controller;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    // the very first install also fires this (clients.claim); only a real update reloads
    if (!hadController || reloaded) return;
    if (isQuiet()) reloadOnce(); else { updateReady = true; renderStatus(); }
  });
  navigator.serviceWorker.register('./sw.js', { scope: './' }).then(r => { swReg = r; }).catch(() => {});
}
// iOS resumes a Home Screen app from memory instead of reloading it: that is the "next open".
function onResumeSW() {
  if (updateReady && isIdle()) reloadOnce();
  else if (swReg) swReg.update().catch(() => {});
}

// ---------------------------------------------------------------- boot
function fatal(err) {
  const box = document.getElementById('tab-home');
  box.hidden = false;
  box.replaceChildren(h('div', { className: 'fatal' },
    h('header', { className: 'runhead' }, h('span', { className: 'runhead-title', text: 'Emma 的英语老师' })),
    h('p', { className: 'status-line danger', role: 'alert' }, icon('alert'), h('span', { text: '打不开这台 iPad 上的数据。' })),
    h('p', { className: 'small', text: '上滑关掉 App 再打开。还不行的话，告诉家长。' }),
    h('p', { className: 'small muted', text: String((err && err.message) || err) }),
    h('div', { className: 'btn-row' }, h('button', { type: 'button', className: 'btn', text: '重新载入', on: { click: () => location.reload() } }))));
}

async function boot() {
  buildTabbar();
  registerSW();
  try {
    for (const r of (await idbStore.kvAll()) || []) if (r && r.key) kvCache.set(r.key, r.value);
    const loaded = loadSettings(kv.peek('settings'));
    settings = loaded.settings;
    if (loaded.migrated) await kv.set('settings', settings).catch(e => console.warn('settings migration:', (e && e.message) || e));
    lastExport = (await idbStore.getMeta('lastExport')) || null;
    await words.load();
    await budget.load();
    curriculum = await curriculumNow();
    let linesData = {};
    try { linesData = await fetchJSON(LINES_FILE); } catch (e) { console.warn('lines:', (e && e.message) || e); }
    // load() reads curriculum/questions.json too (the first-week button questions)
    lines = createLines({ data: linesData, kv, fetchJSON });
    await lines.load();
  } catch (e) {
    console.error(e);
    fatal(e);
    return;
  }
  app.applyTheme((kv.peek('profile', {}) || {}).theme || '');
  checkShrink();
  look = createLookTab(app);
  lib = createLibTab(app);
  home = createHomeTab(app);
  lesson = createLessonView(app);
  dictation = createDictationView(app);
  parent = createParentView(app);
  onboard = createOnboardView(app);
  renderStatus();
  updateBadge();
  showRoute(onboard.needed() ? 'onboard' : 'home', { force: true });
  if (navigator.storage && navigator.storage.persist) navigator.storage.persist().catch(() => {});
  speech.onVoices(() => parent.onChange());   // iOS lists the system voices a moment after launch
  window.addEventListener('online', renderStatus);
  window.addEventListener('offline', renderStatus);
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible') { voice.stop(); return; }
    voice.clearProblem();   // back in the app: the next tap tries the Qwen voice again
    updateBadge();
    renderStatus();
    if (home && home.onChange) home.onChange();
    onResumeSW();
  });
  document.documentElement.dataset.ready = '1';
  // the dictionary loads after the first paint, in small slices; views that rendered before it get the extras
  dict.ready.then(() => {
    for (const v of views) v.update();
    parent.onChange();
  });
  let dictStarted = false;
  const startDict = () => {
    if (dictStarted) return;
    dictStarted = true;
    dict.load().catch(e => { console.warn('dictionary:', (e && e.message) || e); parent.onChange(); });
  };
  requestAnimationFrame(() => setTimeout(startDict, 60));
  setTimeout(startDict, 1500);   // no animation frames in a background tab
}

boot();
